#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    std::vector<bool> flags(p, false);
    int group_count = 0;
    for (int index = 0; index < p; ++index) {
        if (!flags[index]) {
            group_count++;
            int r = index;
            while (!flags[r]) {
                flags[r] = true;
                r = static_cast<int>(fmod(r * k, p));
            }
        }
    }
    if (k == 0) {
        group_count = p;
    } else if (k == 1) {
        group_count = p + 1;
        long long result_value = 1;
        const long long big_mod = 1000000007;
        for (int _ = 0; _ < group_count - 1; ++_) {
            result_value = (result_value * p) % big_mod;
        }
        std::cout << result_value << std::endl;
    }
    return 0;
}
